class Tile extends StatefulWidget {
  const Tile({super.key, required this.label});
  final String label;

  @override
  State<Tile> createState() => _TileState();
}

class _TileState extends State<Tile> {
  late final String initial = widget.label;

  @override
  Widget build(BuildContext context) =>
      Text('$initial/${widget.label}');
}

// In the parent's build:
Column(
  children: swapped
      ? const [Tile(label: 'B'), Tile(label: 'A')]
      : const [Tile(label: 'A'), Tile(label: 'B')],
)

class _CounterState extends State<Counter> {
  int count = 0;

  void onTap() {
    setState(() => count++);
    setState(() => count++);
    print('tapped: $count');
  }

  @override
  Widget build(BuildContext context) {
    print('build: $count');
    return TextButton(
      onPressed: onTap,
      child: Text('$count'),
    );
  }
}

class TodoCubit extends Cubit<List<String>> {
  TodoCubit() : super([]);

  void add(String title) {
    state.add(title);
    emit(state);
  }
}

class _ChildState extends State<Child> {
  @override
  void initState() {
    super.initState();
    print('initState');
  }

  @override
  void didUpdateWidget(covariant Child oldWidget) {
    super.didUpdateWidget(oldWidget);
    print('didUpdateWidget ${oldWidget.value} -> ${widget.value}');
  }

  @override
  Widget build(BuildContext context) {
    print('build ${widget.value}');
    return Text('${widget.value}');
  }
}

