class _NameFieldState extends State<NameField> {
  @override
  Widget build(BuildContext context) {
    final controller = TextEditingController();
    return TextFormField(
      controller: controller,
      decoration: const InputDecoration(labelText: 'Tên'),
      validator: (value) =>
          (value == null || value.isEmpty) ? 'Bắt buộc' : null,
    );
  }
}

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key, required this.isLoggedIn});
  final bool isLoggedIn;

  @override
  Widget build(BuildContext context) {
    if (!isLoggedIn) {
      Navigator.of(context).push(
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );
    }
    return const Scaffold(body: Text('Home'));
  }
}

class _ParentState extends State<Parent> {
  int n = 0;

  @override
  Widget build(BuildContext context) {
    print('Parent $n');
    return Column(
      children: [
        TextButton(
          onPressed: () => setState(() => n++),
          child: const Text('+'),
        ),
        const Label(tag: 'A'),
        Label(tag: 'B'),
      ],
    );
  }
}

// Label is a StatelessWidget whose build
// calls print('Label $tag').

Future<void> load() async {
  setState(() => loading = true);
  final body = await rootBundle.loadString('assets/big.json');
  final list = (jsonDecode(body) as List)
      .map((e) => Product.fromJson(e as Map<String, dynamic>))
      .toList();
  setState(() {
    products = list;
    loading = false;
  });
}

class _LikeButtonState extends State<LikeButton> {
  int likes = 0;

  @override
  Widget build(BuildContext context) {
    return TextButton(
      onPressed: () {
        likes++;
      },
      child: Text('Likes: $likes'),
    );
  }
}

final items = ValueNotifier<List<int>>([]);
items.addListener(() => print('notify ${items.value}'));

items.value.add(1);
items.value = [...items.value, 2];
items.value = items.value;
print('done');

